command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$branch="work/remote-reusable-artifacts-20261005"
$candidate="18935ef28c05b77add6f46e015a64a39eb3cdc7c"
Set-Location -LiteralPath $repo
& git fetch origin $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("remote-reuse-policy-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $env:PYTHONIOENCODING="utf-8"
  & python -X utf8 (Join-Path $temp "tools\winui\check_python_static.py") (Join-Path $temp "tools\winui\remote_evidence_policy.py") (Join-Path $temp "tests\winui\test_remote_evidence_policy.py") (Join-Path $temp "tests\winui\test_remote_windows_task_contract.py")
  if($LASTEXITCODE -ne 0){throw "static check failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 -m unittest tests.winui.test_remote_evidence_policy tests.winui.test_remote_windows_task_contract
  if($LASTEXITCODE -ne 0){throw "infra contracts failed"}
  & git diff --check "0b64535bc651d3efe350db60f08e85dba237c51a..18935ef28c05b77add6f46e015a64a39eb3cdc7c"
  if($LASTEXITCODE -ne 0){throw "diff check failed"}
  Write-Host "REMOTE_REUSABLE_ARTIFACTS_POLICY_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
